def quoted(value):
    return "'" + str(value).replace("'", "''") + "'"

def upgrade():
    op.execute("""CREATE TABLE reporting_units (
        id text PRIMARY KEY,
        name text NOT NULL UNIQUE,
        group_name text NOT NULL,
        extension text NOT NULL,
        phone text NOT NULL,
        source_url text NOT NULL,
        source_page integer NOT NULL CHECK (source_page BETWEEN 1 AND 16),
        source_date date NOT NULL,
        sort_order integer NOT NULL
    )""")
    for index, unit in enumerate(UNITS, 1):
        values = [quoted(unit[key]) for key in ['id','name','group','extension','phone','source_url']]
        values += [str(unit['source_page']), quoted(unit['source_date']), str(index)]
        op.execute('INSERT INTO reporting_units VALUES (' + ','.join(values) + ')')
    op.execute("ALTER TABLE items ADD COLUMN reporting_unit_id text REFERENCES reporting_units(id)")
    op.execute("CREATE INDEX items_reporting_unit_idx ON items(reporting_unit_id)")
    op.execute("""UPDATE items i SET reporting_unit_id = u.id
        FROM organizations o, reporting_units u
        WHERE i.organization_id = o.id AND o.name = u.name""")

def downgrade():
    op.execute("ALTER TABLE items DROP COLUMN reporting_unit_id")
    op.execute("DROP TABLE reporting_units")
